from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        if not nums:
            return -1

        max_val = max(nums)
        if max_val == 0:
            return 0 if k == 0 else -1

        n = len(nums)
        max_abs = max_val * ((n + 1) // 2)
        if abs(k) > max_abs:
            return -1

        offset = max_abs
        mask = (1 << (2 * max_abs + 1)) - 1
        bit0 = 1 << offset

        # Positive product <= limit, no zero:
        # parity 0 means next sign is '+', parity 1 means next sign is '-'.
        pos0 = [0] * (limit + 1)
        pos1 = [0] * (limit + 1)

        # Positive product > limit, no zero. Exact product no longer matters.
        large0 = 0
        large1 = 0

        # Contains at least one zero, product is 0.
        zero0 = 0
        zero1 = 0

        for x in nums:
            if x == 0:
                new_zero0 = zero0
                new_zero1 = zero1 | bit0  # singleton [0]

                # Append 0 to positive-product states: product becomes 0.
                for m in pos0:
                    if m:
                        new_zero1 |= m
                for m in pos1:
                    if m:
                        new_zero0 |= m

                # Append 0 to large positive states: product becomes 0.
                if large0:
                    new_zero1 |= large0
                if large1:
                    new_zero0 |= large1

                # Append 0 to already-zero states.
                if zero0:
                    new_zero1 |= zero0
                if zero1:
                    new_zero0 |= zero1

                zero0, zero1 = new_zero0, new_zero1

            else:
                new_pos0 = pos0[:]
                new_pos1 = pos1[:]
                new_large0 = large0
                new_large1 = large1
                new_zero0 = zero0
                new_zero1 = zero1

                # Singleton [x].
                if x <= limit:
                    new_pos1[x] |= 1 << (offset + x)
                else:
                    new_large1 |= 1 << (offset + x)

                threshold = limit // x

                # From positive states whose product stays <= limit.
                for p in range(1, threshold + 1):
                    np = p * x

                    m = pos0[p]
                    if m:
                        new_pos1[np] |= (m << x) & mask

                    m = pos1[p]
                    if m:
                        new_pos0[np] |= (m >> x)

                # From positive states whose product becomes > limit.
                for p in range(threshold + 1, limit + 1):
                    m = pos0[p]
                    if m:
                        new_large1 |= (m << x) & mask

                    m = pos1[p]
                    if m:
                        new_large0 |= (m >> x)

                # From large positive states.
                if large0:
                    new_large1 |= (large0 << x) & mask
                if large1:
                    new_large0 |= (large1 >> x)

                # From zero-product states.
                if zero0:
                    new_zero1 |= (zero0 << x) & mask
                if zero1:
                    new_zero0 |= (zero1 >> x)

                pos0, pos1 = new_pos0, new_pos1
                large0, large1 = new_large0, new_large1
                zero0, zero1 = new_zero0, new_zero1

        target = 1 << (offset + k)

        for p in range(limit, 0, -1):
            if (pos0[p] & target) or (pos1[p] & target):
                return p

        if (zero0 & target) or (zero1 & target):
            return 0

        return -1

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    T = next(it)
    out = []
    INF = 10**30

    for _ in range(T):
        N = next(it)
        K = next(it)
        M = 2 * K

        X = [0] * N
        Y = [0] * N
        Z = [0] * N
        m = [0] * N

        for i in range(N):
            x = next(it)
            y = next(it)
            z = next(it)
            X[i] = x
            Y[i] = y
            Z[i] = z
            if x >= y and x >= z:
                m[i] = x
            elif y >= z:
                m[i] = y
            else:
                m[i] = z

        idx = list(range(N))
        idx.sort(key=m.__getitem__, reverse=True)

        col = [-1] * N
        parity = [0, 0, 0]
        base = 0

        for i in idx[:M]:
            base += m[i]
            if X[i] == m[i]:
                c = 0
            elif Y[i] == m[i]:
                c = 1
            else:
                c = 2
            col[i] = c
            parity[c] ^= 1

        odd = [d for d in range(3) if parity[d]]
        if not odd:
            out.append(str(base))
            continue

        a, b = odd[0], odd[1]
        c = 3 - a - b
        coords = (X, Y, Z)

        # Selected items: top-3 smallest m for each selected color.
        top3_min_m = [[], [], []]
        min_m = [INF] * 3
        sum2_min_m = [INF] * 3

        # Recolor costs: selected color d -> target color e.
        recolor_min = [[INF] * 3 for _ in range(3)]
        top3_recolor = [[[] for _ in range(3)] for _ in range(3)]

        # Unselected items: top-3 largest value for each color.
        top3_unsel = [[], [], []]
        top1_unsel = [-1, -1, -1]
        top2_sum_unsel = [INF] * 3

        for i in range(N):
            d = col[i]
            if d != -1:
                mi = m[i]

                lst = top3_min_m[d]
                if len(lst) < 3:
                    lst.append((mi, i))
                    lst.sort()
                else:
                    if mi < lst[-1][0]:
                        lst[-1] = (mi, i)
                        lst.sort()

                for e in range(3):
                    if e == d:
                        continue
                    cost = mi - coords[e][i]
                    if cost < recolor_min[d][e]:
                        recolor_min[d][e] = cost

                    lst2 = top3_recolor[d][e]
                    if len(lst2) < 3:
                        lst2.append((cost, i))
                        lst2.sort()
                    else:
                        if cost < lst2[-1][0]:
                            lst2[-1] = (cost, i)
                            lst2.sort()
            else:
                for e in range(3):
                    val = coords[e][i]
                    lst = top3_unsel[e]
                    if len(lst) < 3:
                        lst.append((val, i))
                        lst.sort(reverse=True)
                    else:
                        if val > lst[-1][0]:
                            lst[-1] = (val, i)
                            lst.sort(reverse=True)

        for d in range(3):
            lst = top3_min_m[d]
            if lst:
                min_m[d] = lst[0][0]
                if len(lst) >= 2:
                    sum2_min_m[d] = lst[0][0] + lst[1][0]

        for e in range(3):
            lst = top3_unsel[e]
            if lst:
                top1_unsel[e] = lst[0][0]
                if len(lst) >= 2:
                    top2_sum_unsel[e] = lst[0][0] + lst[1][0]

        # best_pair_unsel[d][e] = max_{u != v, unselected} value_d[u] + value_e[v]
        best_pair_unsel = [[INF] * 3 for _ in range(3)]
        for d in range(3):
            for e in range(3):
                if d == e:
                    best_pair_unsel[d][e] = top2_sum_unsel[d]
                else:
                    ids = set()
                    for _, idx2 in top3_unsel[d]:
                        ids.add(idx2)
                    for _, idx2 in top3_unsel[e]:
                        ids.add(idx2)
                    if len(ids) >= 2:
                        best = -1
                        for u in ids:
                            vu = coords[d][u]
                            for v in ids:
                                if u != v:
                                    val = vu + coords[e][v]
                                    if val > best:
                                        best = val
                        best_pair_unsel[d][e] = best if best >= 0 else INF

        # One exchange fixing parity {a, b}.
        one = min(recolor_min[a][b], recolor_min[b][a])
        if min_m[a] < INF and top1_unsel[b] >= 0:
            one = min(one, min_m[a] - top1_unsel[b])
        if min_m[b] < INF and top1_unsel[a] >= 0:
            one = min(one, min_m[b] - top1_unsel[a])
        if one < 0:
            one = 0

        ans2 = INF

        # Two exchanges: types (a,c) and (b,c).
        # 1) selected a -> c, selected b -> c
        if recolor_min[a][c] < INF and recolor_min[b][c] < INF:
            val = recolor_min[a][c] + recolor_min[b][c]
            if val < ans2:
                ans2 = val
        if recolor_min[a][c] < INF and min_m[b] < INF and top1_unsel[c] >= 0:
            val = recolor_min[a][c] + min_m[b] - top1_unsel[c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[a] < INF and top1_unsel[c] >= 0 and recolor_min[b][c] < INF:
            val = min_m[a] - top1_unsel[c] + recolor_min[b][c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[a] < INF and min_m[b] < INF and top2_sum_unsel[c] < INF:
            val = min_m[a] + min_m[b] - top2_sum_unsel[c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val

        # 2) selected a -> c, selected c -> b
        if recolor_min[a][c] < INF and recolor_min[c][b] < INF:
            val = recolor_min[a][c] + recolor_min[c][b]
            if val < ans2:
                ans2 = val
        if recolor_min[a][c] < INF and min_m[c] < INF and top1_unsel[b] >= 0:
            val = recolor_min[a][c] + min_m[c] - top1_unsel[b]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[a] < INF and top1_unsel[c] >= 0 and recolor_min[c][b] < INF:
            val = min_m[a] - top1_unsel[c] + recolor_min[c][b]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[a] < INF and min_m[c] < INF and best_pair_unsel[c][b] < INF:
            val = min_m[a] + min_m[c] - best_pair_unsel[c][b]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val

        # 3) selected c -> a, selected b -> c
        if recolor_min[c][a] < INF and recolor_min[b][c] < INF:
            val = recolor_min[c][a] + recolor_min[b][c]
            if val < ans2:
                ans2 = val
        if recolor_min[c][a] < INF and min_m[b] < INF and top1_unsel[c] >= 0:
            val = recolor_min[c][a] + min_m[b] - top1_unsel[c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[c] < INF and top1_unsel[a] >= 0 and recolor_min[b][c] < INF:
            val = min_m[c] - top1_unsel[a] + recolor_min[b][c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val
        if min_m[c] < INF and min_m[b] < INF and best_pair_unsel[a][c] < INF:
            val = min_m[c] + min_m[b] - best_pair_unsel[a][c]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val

        # 4) selected c -> a, selected c -> b (two distinct selected c-items)
        def min_distinct_recolor_pair(d, e1, e2):
            ids = set()
            for _, idx2 in top3_recolor[d][e1]:
                ids.add(idx2)
            for _, idx2 in top3_recolor[d][e2]:
                ids.add(idx2)
            if len(ids) < 2:
                return INF
            best = INF
            for i in ids:
                cost1 = m[i] - coords[e1][i]
                if cost1 < 0:
                    cost1 = 0
                for k in ids:
                    if i == k:
                        continue
                    cost2 = m[k] - coords[e2][k]
                    if cost2 < 0:
                        cost2 = 0
                    val = cost1 + cost2
                    if val < best:
                        best = val
            return best

        def min_distinct_recolor_swap(d, e_recolor, e_unsel):
            const = top1_unsel[e_unsel]
            if const < 0:
                return INF
            ids = set()
            for _, idx2 in top3_recolor[d][e_recolor]:
                ids.add(idx2)
            for _, idx2 in top3_min_m[d]:
                ids.add(idx2)
            if len(ids) < 2:
                return INF
            best = INF
            for i in ids:
                cost1 = m[i] - coords[e_recolor][i]
                if cost1 < 0:
                    cost1 = 0
                for k in ids:
                    if i == k:
                        continue
                    cost2 = m[k] - const
                    if cost2 < 0:
                        cost2 = 0
                    val = cost1 + cost2
                    if val < best:
                        best = val
            return best

        def min_distinct_swap_recolor(d, e_unsel, e_recolor):
            const = top1_unsel[e_unsel]
            if const < 0:
                return INF
            ids = set()
            for _, idx2 in top3_min_m[d]:
                ids.add(idx2)
            for _, idx2 in top3_recolor[d][e_recolor]:
                ids.add(idx2)
            if len(ids) < 2:
                return INF
            best = INF
            for i in ids:
                cost1 = m[i] - const
                if cost1 < 0:
                    cost1 = 0
                for k in ids:
                    if i == k:
                        continue
                    cost2 = m[k] - coords[e_recolor][k]
                    if cost2 < 0:
                        cost2 = 0
                    val = cost1 + cost2
                    if val < best:
                        best = val
            return best

        val = min_distinct_recolor_pair(c, a, b)
        if val < ans2:
            ans2 = val
        val = min_distinct_recolor_swap(c, a, b)
        if val < ans2:
            ans2 = val
        val = min_distinct_swap_recolor(c, a, b)
        if val < ans2:
            ans2 = val
        if sum2_min_m[c] < INF and best_pair_unsel[a][b] < INF:
            val = sum2_min_m[c] - best_pair_unsel[a][b]
            if val < 0:
                val = 0
            if val < ans2:
                ans2 = val

        gap = min(one, ans2)
        if gap < 0:
            gap = 0
        out.append(str(base - gap))

    sys.stdout.write("\n".join(out))

