import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    S = data[1]
    T = data[2]

    target = [-1] * 26

    for s, t in zip(S, T):
        a = ord(s) - ord('a')
        b = ord(t) - ord('a')
        if target[a] == -1:
            target[a] = b
        elif target[a] != b:
            print(-1)
            return

    appearing = [i for i in range(26) if target[i] != -1]
    appearing_set = set(appearing)

    distinct_targets = set(target[i] for i in appearing)

    base_ops = sum(1 for i in appearing if target[i] != i)

    total_in = [0] * 26
    for i in appearing:
        total_in[target[i]] += 1

    out = [-1] * 26
    for i in appearing:
        if target[i] != i and target[i] in appearing_set:
            out[i] = target[i]

    state = [0] * 26
    bad_cycles = 0

    for start in appearing:
        if state[start] != 0:
            continue

        stack = []
        pos = {}
        cur = start

        while cur != -1 and state[cur] == 0:
            state[cur] = 1
            pos[cur] = len(stack)
            stack.append(cur)
            cur = out[cur]

        if cur != -1 and state[cur] == 1:
            cycle = stack[pos[cur]:]
            is_bad = True
            for v in cycle:
                if total_in[v] > 1:
                    is_bad = False
                    break
            if is_bad:
                bad_cycles += 1

        for v in stack:
            state[v] = 2

    has_buffer = (len(appearing) < 26) or (len(distinct_targets) < len(appearing))

    if bad_cycles > 0 and not has_buffer:
        print(-1)
    else:
        print(base_ops + bad_cycles)

