from typing import List
from bisect import bisect_right

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        if not queries:
            return 0

        max_r = max(r for _, r in queries)

        # powers[i] = 4^i
        powers = [1]
        while powers[-1] <= max_r:
            powers.append(powers[-1] * 4)

        # pref[i] = sum of depths for all numbers from 1 to 4^i - 1
        pref = [0] * len(powers)
        for i in range(1, len(powers)):
            pref[i] = pref[i - 1] + i * (powers[i] - powers[i - 1])

        def prefix_sum(n: int) -> int:
            """Sum of operations needed for each number in [1, n]."""
            if n <= 0:
                return 0
            k = bisect_right(powers, n)
            return pref[k - 1] + k * (n - powers[k - 1] + 1)

        ans = 0
        for l, r in queries:
            total_depth = prefix_sum(r) - prefix_sum(l - 1)
            max_depth = bisect_right(powers, r)
            ans += max(max_depth, (total_depth + 1) // 2)

        return ans

