import heapq

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [None]
        count = [0]
        depth = [0]
        is_terminal = [False]
        terminals = []
        max_len = 0

        for w in words:
            lw = len(w)
            if lw > max_len:
                max_len = lw
            node = 0
            count[0] += 1
            for ch in w:
                ch_to = children[node]
                if ch_to is None:
                    ch_to = {}
                    children[node] = ch_to
                nxt = ch_to.get(ch)
                if nxt is None:
                    nxt = len(children)
                    ch_to[ch] = nxt
                    children.append(None)
                    count.append(0)
                    depth.append(depth[node] + 1)
                    is_terminal.append(False)
                node = nxt
                count[node] += 1
            is_terminal[node] = True
            terminals.append(node)

        good = [c >= k for c in count]
        good_plus = [c >= k + 1 for c in count]

        active = [0] * (max_len + 1)
        for i, g in enumerate(good):
            if g:
                active[depth[i]] += 1
        heap = [-d for d, cnt in enumerate(active) if cnt]
        heapq.heapify(heap)

        ans_node = [-1] * len(children)
        stack = [(0, 0, -1)]
        heappush = heapq.heappush
        heappop = heapq.heappop

        while stack:
            u, state, parent_path = stack.pop()
            if state == 0:
                if good[u]:
                    active[depth[u]] -= 1
                cur_path = parent_path
                if good_plus[u]:
                    du = depth[u]
                    if du > cur_path:
                        cur_path = du
                if is_terminal[u]:
                    while heap and active[-heap[0]] == 0:
                        heappop(heap)
                    outside = -heap[0] if heap else 0
                    ans_node[u] = outside if outside > cur_path else cur_path
                stack.append((u, 1, cur_path))
                ch_to = children[u]
                if ch_to is not None:
                    for v in ch_to.values():
