class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(INF, fact[i - 1] * i)

        total_odd = (n + 1) // 2
        total_even = n // 2

        def count_suffix(rem_odd: int, rem_even: int, last: int) -> int:
            if rem_odd < 0 or rem_even < 0:
                return 0
            if rem_odd == 0 and rem_even == 0:
                return 1

            patterns = 0

            if last == -1:
                if rem_odd == rem_even or rem_odd == rem_even + 1:
                    patterns += 1
                if rem_even == rem_odd or rem_even == rem_odd + 1:
                    patterns += 1
            elif last == 0:  # previous was odd, suffix must start even
                if rem_even == rem_odd or rem_even == rem_odd + 1:
                    patterns = 1
            else:  # previous was even, suffix must start odd
                if rem_odd == rem_even or rem_odd == rem_even + 1:
                    patterns = 1

            if patterns == 0:
                return 0

            return min(INF, fact[rem_odd] * fact[rem_even] * patterns)

        if k > count_suffix(total_odd, total_even, -1):
            return []

        used = [False] * (n + 1)
        used_odd = 0
        used_even = 0
        last = -1
        ans = []

        for _ in range(n):
            chosen = None

            for x in range(1, n + 1):
                if used[x]:
                    continue

                is_odd = x & 1

                if last == 0 and is_odd:
                    continue
                if last == 1 and not is_odd:
                    continue

                if is_odd:
                    cnt = count_suffix(
                        total_odd - used_odd - 1,
                        total_even - used_even,
                        0
                    )
                else:
                    cnt = count_suffix(
                        total_odd - used_odd,
                        total_even - used_even - 1,
                        1
                    )

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen & 1:
                used_odd += 1
                last = 0
            else:
                used_even += 1
                last = 1

        return ans

