class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        if k <= 1:
            return 0

        # Map every boundary point to its perimeter coordinate on a circle
        # of circumference 4 * side.
        C = 4 * side
        t = []
        for x, y in points:
            if y == 0:
                t.append(x)
            elif x == side:
                t.append(side + y)
            elif y == side:
                t.append(3 * side - x)
            else:
                t.append(4 * side - y)

        t.sort()
        n = len(t)
        if n < k:
            return 0

        # For k >= 4, the answer is at most side. Also, on a circle of
        # circumference C, k points cannot all be farther than C // k apart.
        hi = C // k

        t2 = t + [x + C for x in t]
        m = 2 * n
        steps = range(k - 1)

        def can(d: int) -> bool:
            # Distinct integer perimeter coordinates are at least 1 apart.
            if d <= 1:
                return True

            # nxt[i] = first index j > i with t2[j] - t2[i] >= d
            nxt = [m] * m
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = t2[i] + d
                while j < m and t2[j] < target:
                    j += 1
                nxt[i] = j

            limit = C - d

            # Try every point as the first selected point in circular order.
            for i in range(n):
                idx = i
                end = i + n
                start_t = t2[i]

                for _ in steps:
                    idx = nxt[idx]
                    if idx >= end:
                        break
                else:
                    # The wrap-around gap must also be at least d.
                    if t2[idx] - start_t <= limit:
                        return True

            return False

        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

