class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        n = len(grid)
        m = len(grid[0])
        N = n * m

        vals = [x for row in grid for x in row]
        ones = [i for i, v in enumerate(vals) if v == 1]
        if not ones:
            return 0

        # cont2[d][i]: max cells after i in direction d, starting with expected 2
        # cont0[d][i]: max cells after i in direction d, starting with expected 0
        cont2 = [array('H', [0]) * N for _ in range(4)]
        cont0 = [array('H', [0]) * N for _ in range(4)]

        # 0: down-right, 1: down-left, 2: up-left, 3: up-right
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        for d, (dr, dc) in enumerate(dirs):
            c2 = cont2[d]
            c0 = cont0[d]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)

            for r in rows:
                nr = r + dr
                if nr < 0 or nr >= n:
                    continue

                base = r * m
                nbase = nr * m

                if dc == 1:
                    for c in range(m - 1):
                        i = base + c
                        j = nbase + c + 1
                        v = vals[j]
                        if v == 2:
                            c2[i] = c0[j] + 1
                        elif v == 0:
                            c0[i] = c2[j] + 1
                else:
                    for c in range(1, m):
                        i = base + c
                        j = nbase + c - 1
                        v = vals[j]
                        if v == 2:
                            c2[i] = c0[j] + 1
                        elif v == 0:
                            c0[i] = c2[j] + 1

        # Clockwise 90-degree turn among diagonal directions
        cw = (1, 2, 3, 0)
        deltas = [dr * m + dc for dr, dc in dirs]

        ans = 0

        for d in range(4):
            c2d = cont2[d]
            c0cw = cont0[cw[d]]
            c2cw = cont2[cw[d]]
            delta = deltas[d]

            for i in ones:
                straight_len = c2d[i] + 1
                if straight_len > ans:
                    ans = straight_len

                if straight_len > 1:
                    t = i + delta
                    for a in range(1, straight_len):
                        if a & 1:
                            total = a + 1 + c0cw[t]
                        else:
                            total = a + 1 + c2cw[t]

                        if total > ans:
                            ans = total

                        t += delta

        return ans

