class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        targets = []
        for t in target:
            if t not in targets:
                targets.append(t)

        m = len(targets)
        size = 1 << m
        all_mask = size - 1

        lcm = [1] * size
        for mask in range(1, size):
            lsb = mask & -mask
            i = lsb.bit_length() - 1
            prev = mask ^ lsb
            a = lcm[prev]
            b = targets[i]
            lcm[mask] = (a // gcd(a, b)) * b

        transitions = []
        for mask in range(size):
            rem = all_mask ^ mask
            sub = rem
            pairs = []
            while sub:
                pairs.append((sub, mask | sub))
                sub = (sub - 1) & rem
            if pairs:
                transitions.append((mask, pairs))

        INF = 10 ** 30
        dp = [INF] * size
        dp[0] = 0

        for x in nums:
            cost = [0] * size
            for mask in range(1, size):
                L = lcm[mask]
                r = x % L
                if r:
                    cost[mask] = L - r

            new_dp = dp[:]
            for mask, pairs in transitions:
                base = dp[mask]
                if base == INF:
                    continue
                for sub, nm in pairs:
                    val = base + cost[sub]
                    if val < new_dp[nm]:
                        new_dp[nm] = val

            dp = new_dp
            if dp[all_mask] == 0:
                return 0

        return dp[all_mask]

