class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        s = k + 1

        def count_pairs(a: int, b: int) -> int:
            A = a if a < k else k
            B = b if b < k else k
            t = s - B
            if t > A:
                t = A
            d = A - t
            return t * B + d * s - (t + 1 + A) * d // 2

        def sum_min() -> int:
            prev = [-1] * n
            stack = []

            for i, x in enumerate(nums):
                while stack and nums[stack[-1]] >= x:
                    stack.pop()
                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            total = 0
            stack = []

            for i in range(n - 1, -1, -1):
                x = nums[i]
                while stack and nums[stack[-1]] > x:
                    stack.pop()
                nxt = stack[-1] if stack else n
                total += x * count_pairs(i - prev[i], nxt - i)
                stack.append(i)

            return total

        def sum_max() -> int:
            prev = [-1] * n
            stack = []

            for i, x in enumerate(nums):
                while stack and nums[stack[-1]] <= x:
                    stack.pop()
                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            total = 0
            stack = []

            for i in range(n - 1, -1, -1):
                x = nums[i]
                while stack and nums[stack[-1]] < x:
                    stack.pop()
                nxt = stack[-1] if stack else n
                total += x * count_pairs(i - prev[i], nxt - i)
                stack.append(i)

            return total

        return sum_min() + sum_max()

