import sys
from bisect import bisect_left


def build_sequence(perm, balls, x, n):
    pos = [-1] * (n + 1)
    nodes = []

    cur = x
    for _ in range(n):
        pos[cur] = len(nodes)
        nodes.append(cur)
        cur = perm[cur]
        if cur == x:
            break

    min_pos = n + 1
    for i, v in enumerate(balls):
        if v:
            p = pos[i]
            if p == -1:
                return None, False
            if p > 0 and p < min_pos:
                min_pos = p

    if min_pos == n + 1:
        return [], True
    return nodes[min_pos:], True


