from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        T1 = T + 1

        present = bytearray(T1)
        isolated = 0
        count_le = 0
        max_le = 0

        for x in nums:
            if x <= T:
                if not present[x]:
                    present[x] = 1
                    count_le += 1
                    if x > max_le:
                        max_le = x
            else:
                isolated += 1

        if count_le == 0:
            return isolated
        if present[1] or count_le == 1:
            return isolated + 1

        parent = list(range(T1))
        size = [1] * T1

        def find(a: int, parent=parent) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        first = [0] * T1
        components = count_le

        for d in range(2, max_le + 1):
            if present[d]:
                rd = find(d)
                for m in range(d, T1, d):
                    f = first[m]
                    if f == 0:
                        first[m] = d
                    else:
                        rf = find(f)
                        if rd != rf:
                            components -= 1
                            if size[rd] < size[rf]:
                                parent[rd] = rf
                                size[rf] += size[rd]
                                rd = rf
                            else:
                                parent[rf] = rd
                                size[rd] += size[rf]

                            if components == 1:
                                return isolated + 1

        return components + isolated
